examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchCountrySelect(
        selected = country,
        onSelectedChange = {
            country = it
            region = null
        },
        countries = listOf({{country.options.0}}, {{country.options.1}}, {{country.options.2}}, {{country.options.3}}, {{country.options.4}}, {{country.options.5}}),
        labels = MonarchCountrySelectLabels(label = {{country.label}}),
    )
    MonarchRegionSelect(
        country = country,
        selected = region,
        onSelectedChange = { region = it },
    )
}

